import * as fs from 'node:fs';
import * as http from 'node:http';
import * as os from 'node:os';
import * as path from 'node:path';
import process from 'node:process';
function main(): void {
  const file = path.join(os.tmpdir(), 'thaw-compat-bytes-' + process.pid + '.bin');
  fs.writeFileSync(file, Buffer.from([0x50, 0x4b, 0x03, 0x04, 1, 2, 3, 250]));
  const srv = http.createServer((req: any, res: any) => {
    const body: Uint8Array = fs.readFileSync(file);
    res.writeHead(200, { 'content-type': 'application/octet-stream' });
    res.end(body);
  });
  srv.listen(0, '127.0.0.1', (): void => {
    const port = (srv.address() as any).port;
    http.get({ host: '127.0.0.1', port, path: '/' }, (res: any): void => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer): void => { chunks.push(chunk); });
      res.on('end', (): void => {
        const all = Buffer.concat(chunks);
        console.log(res.statusCode, all.length, all[0], all[1], all.toString('hex'));
        srv.close();
        fs.rmSync(file);
      });
    });
  });
}
